## Manifest 完整接口定义

以下 JSON 与插件包内实际 `manifest.json` 逐字段一致，覆盖插件身份、权限、配置、鉴权、参数、校验、创建、Agent、查询、取消、结果下载、响应和 Agent 响应映射。`documentation` 字段的值就是当前完整文档；为避免文档在自身内部无限递归，JSON 中仅用等义占位文本表示正文。

```json
{
  "apiVersion": "yingce.plugin/v2",
  "id": "tencent-vod-vs",
  "name": "腾讯云 VOD VS 直连",
  "version": "1.0.0",
  "author": "乐见画布",
  "description": "管理员配置腾讯云点播，自主直连 VS 视频生成，不经过源点动力。",
  "permissions": [
    "generation.run",
    "media.read"
  ],
  "runtime": {
    "backend": "declarative"
  },
  "configuration": {
    "fields": [
      {
        "name": "apiKey",
        "type": "secret",
        "label": "SecretId",
        "required": true
      },
      {
        "name": "secretKey",
        "type": "secret",
        "label": "SecretKey",
        "required": true
      }
    ]
  },
  "contributes": {
    "providers": [
      {
        "id": "tencent-vod-vs",
        "label": "腾讯云 VOD VS 直连",
        "capabilities": [
          "video"
        ],
        "scopes": [
          "admin.system-channel",
          "canvas",
          "creation",
          "agent"
        ],
        "baseUrl": "https://vod.tencentcloudapi.com",
        "auth": {
          "type": "tc3",
          "field": "apiKey",
          "secretField": "secretKey",
          "service": "vod"
        },
        "requiresPublicMediaUrls": true,
        "detachedPolling": true,
        "parameters": [
          {
            "name": "model",
            "type": "string",
            "required": true,
            "mapping": "ModelVersion",
            "description": "VS 2.0、2.0-fast、2.0-mini 或 2.5。"
          },
          {
            "name": "prompt",
            "type": "string",
            "required": true,
            "mapping": "Prompt",
            "description": "视频提示词。"
          },
          {
            "name": "images",
            "type": "media[]",
            "required": false,
            "mapping": "FileInfos",
            "description": "首帧、尾帧或参考图片。"
          },
          {
            "name": "videos",
            "type": "media[]",
            "required": false,
            "mapping": "FileInfos",
            "description": "参考视频。"
          },
          {
            "name": "audios",
            "type": "media[]",
            "required": false,
            "mapping": "FileInfos",
            "description": "参考音频。"
          },
          {
            "name": "duration",
            "type": "integer",
            "required": false,
            "mapping": "OutputConfig.Duration",
            "description": "秒数或自动时长。"
          },
          {
            "name": "aspectRatio",
            "type": "string",
            "required": false,
            "mapping": "OutputConfig.AspectRatio",
            "description": "输出画幅。"
          },
          {
            "name": "resolution",
            "type": "string",
            "required": false,
            "mapping": "OutputConfig.Resolution",
            "description": "输出分辨率。"
          },
          {
            "name": "generateAudio",
            "type": "boolean",
            "required": false,
            "mapping": "OutputConfig.AudioGeneration",
            "description": "是否生成音频。"
          },
          {
            "name": "watermark",
            "type": "boolean",
            "required": false,
            "mapping": "OutputConfig.LogoAdd",
            "description": "是否添加水印。"
          }
        ],
        "create": {
          "method": "POST",
          "path": "/",
          "originPath": true,
          "contentType": "application/json",
          "headers": {
            "Content-Type": "application/json; charset=utf-8",
            "X-TC-Action": "CreateAigcVideoTask",
            "X-TC-Version": "2018-07-17",
            "X-TC-Region": "ap-guangzhou"
          },
          "body": {
            "$ref": "request.extra.tencentVod"
          }
        },
        "poll": {
          "method": "POST",
          "path": "/",
          "originPath": true,
          "contentType": "application/json",
          "headers": {
            "Content-Type": "application/json; charset=utf-8",
            "X-TC-Action": "DescribeTaskDetail",
            "X-TC-Version": "2018-07-17",
            "X-TC-Region": "ap-guangzhou"
          },
          "body": {
            "TaskId": {
              "$ref": "taskId"
            },
            "SubAppId": {
              "$ref": "request.extra.tencentVodAppId"
            }
          }
        },
        "response": {
          "taskId": {
            "$coalesce": [
              {
                "$ref": "response.Response.TaskId"
              },
              {
                "$ref": "response.Response.AigcVideoTask.TaskId"
              },
              {
                "$ref": "taskId"
              }
            ]
          },
          "status": {
            "$switch": {
              "cases": [
                {
                  "when": {
                    "$and": [
                      {
                        "$eq": [
                          {
                            "$ref": "response.Response.AigcVideoTask.Status"
                          },
                          "FINISH"
                        ]
                      },
                      {
                        "$eq": [
                          {
                            "$ref": "response.Response.AigcVideoTask.ErrCode"
                          },
                          0
                        ]
                      }
                    ]
                  },
                  "then": "succeeded"
                },
                {
                  "when": {
                    "$eq": [
                      {
                        "$ref": "response.Response.AigcVideoTask.Status"
                      },
                      "PROCESSING"
                    ]
                  },
                  "then": "processing"
                },
                {
                  "when": {
                    "$ref": "response.Response.TaskId"
                  },
                  "then": "pending"
                }
              ],
              "default": "failed"
            }
          },
          "message": {
            "$coalesce": [
              {
                "$ref": "response.Response.Error.Message"
              },
              {
                "$ref": "response.Response.AigcVideoTask.Message"
              },
              "腾讯云点播未返回有效的视频任务结果"
            ]
          },
          "errorPaths": [
            "Response.Error",
            "Response.AigcVideoTask.ErrCode"
          ],
          "videos": {
            "$if": {
              "condition": {
                "$and": [
                  {
                    "$eq": [
                      {
                        "$ref": "response.Response.AigcVideoTask.Status"
                      },
                      "FINISH"
                    ]
                  },
                  {
                    "$eq": [
                      {
                        "$ref": "response.Response.AigcVideoTask.ErrCode"
                      },
                      0
                    ]
                  }
                ]
              },
              "then": {
                "$first": {
                  "$map": {
                    "from": {
                      "$filter": {
                        "from": {
                          "$ref": "response.Response.AigcVideoTask.Output.FileInfos"
                        },
                        "as": "file",
                        "where": {
                          "$and": [
                            {
                              "$not": {
                                "$ref": "file.UsageType"
                              }
                            },
                            {
                              "$in": [
                                {
                                  "$lower": {
                                    "$ref": "file.FileType"
                                  }
                                },
                                [
                                  "",
                                  "mp4",
                                  "mov",
                                  "webm",
                                  "mkv",
                                  "flv",
                                  "m3u8"
                                ]
                              ]
                            },
                            {
                              "$ref": "file.FileUrl"
                            }
                          ]
                        }
                      }
                    },
                    "as": "file",
                    "in": {
                      "$ref": "file.FileUrl"
                    }
                  }
                }
              },
              "else": null
            }
          },
          "resultEphemeral": true
        }
      }
    ]
  },
  "documentation": "<当前插件的完整 documentation，由 README.md 与 docs/interface.md 拼接而成；为避免 JSON 递归，此处不重复展开正文。>"
}
```
<!-- YINGCE_MANIFEST_CONTRACT_END -->
